'use strict';
const RealExamples=(()=>{
  const RAW_CASES=[{"key":"bahodopi","name":"Bahodopi","status":"success","province":"Central Sulawesi","population":45434,"officeMonthly":460000,"managerMonthly":3500000,"title":{"en":"Rapid scaling through reinvestment in growth","id":"Skala cepat melalui reinvestasi pada pertumbuhan"},"summary":{"en":"Once early demand became visible, the franchisee did not reduce promotion and instead increased it step by step. Advertising became an accelerator for an already growing market, supporting momentum and allowing the operation to move quickly from launch to scaling.","id":"Setelah tanda-tanda awal permintaan mulai terlihat, franchisee tidak mengurangi promosi dan justru meningkatkannya secara bertahap. Iklan menjadi pendorong bagi pasar yang sudah tumbuh, menjaga momentum dan membantu unit beralih dengan cepat dari tahap peluncuran ke tahap ekspansi."},"bullets":{"en":["Order volume maintained steady growth throughout the year.","Advertising investment increased as demand was confirmed and supported further scaling.","The investment pays back in month 4."],"id":["Volume pesanan mempertahankan pertumbuhan yang stabil sepanjang tahun.","Investasi iklan ditingkatkan setelah permintaan terbukti dan mendukung ekspansi berikutnya.","Investasi kembali pada bulan ke-4."]},"rows":[{"n":1,"year":2025,"calendarMonth":1,"completedOrders":223,"completedRideValue":3739200.0,"advertising":0.0},{"n":2,"year":2025,"calendarMonth":2,"completedOrders":4873,"completedRideValue":66785100.0,"advertising":0.0},{"n":3,"year":2025,"calendarMonth":3,"completedOrders":8119,"completedRideValue":116911300.0,"advertising":300000.0},{"n":4,"year":2025,"calendarMonth":4,"completedOrders":9813,"completedRideValue":146582100.0,"advertising":430000.0},{"n":5,"year":2025,"calendarMonth":5,"completedOrders":17399,"completedRideValue":249541000.0,"advertising":3000000.0},{"n":6,"year":2025,"calendarMonth":6,"completedOrders":23194,"completedRideValue":333443600.0,"advertising":11500000.0},{"n":7,"year":2025,"calendarMonth":7,"completedOrders":32228,"completedRideValue":451782800.0,"advertising":20000000.0},{"n":8,"year":2025,"calendarMonth":8,"completedOrders":41795,"completedRideValue":594379798.0,"advertising":12000000.0},{"n":9,"year":2025,"calendarMonth":9,"completedOrders":50785,"completedRideValue":705956900.0,"advertising":15000000.0},{"n":10,"year":2025,"calendarMonth":10,"completedOrders":63764,"completedRideValue":880303300.0,"advertising":25000000.0},{"n":11,"year":2025,"calendarMonth":11,"completedOrders":72589,"completedRideValue":1006374200.0,"advertising":11000000.0},{"n":12,"year":2025,"calendarMonth":12,"completedOrders":82484,"completedRideValue":1138476200.0,"advertising":5000000.0}]},{"key":"tanjung-balai-karimun","name":"Tanjung Balai Karimun","status":"success","province":"Riau","population":50876,"officeMonthly":2100000,"managerMonthly":1500000,"title":{"en":"Balanced growth with controlled investment","id":"Pertumbuhan seimbang dengan investasi yang terkontrol"},"summary":{"en":"Growth here was not driven by a sharp increase in spending, but by consistent development of the territory. After establishing a base level of demand, the franchisee made advertising a regular part of operations and gradually increased investment while maintaining a stable, controlled pace.","id":"Pertumbuhan di sini tidak dibangun melalui lonjakan anggaran, tetapi melalui pengembangan wilayah yang konsisten. Setelah permintaan dasar terbentuk, franchisee menjadikan iklan sebagai bagian rutin dari operasional dan meningkatkan investasi secara bertahap dengan tetap menjaga laju pertumbuhan yang stabil dan terkontrol."},"bullets":{"en":["Growth developed gradually without sharp setbacks.","Advertising became a regular part of operations after the launch period and increased as the territory developed.","The project pays back in month 6."],"id":["Pertumbuhan terbentuk secara bertahap tanpa penurunan tajam.","Iklan menjadi bagian rutin dari operasional setelah periode awal dan ditingkatkan seiring perkembangan wilayah.","Proyek kembali modal pada bulan ke-6."]},"rows":[{"n":1,"year":2024,"calendarMonth":5,"completedOrders":750,"completedRideValue":12362100.0,"advertising":0.0},{"n":2,"year":2024,"calendarMonth":6,"completedOrders":4609,"completedRideValue":77379600.0,"advertising":0.0},{"n":3,"year":2024,"calendarMonth":7,"completedOrders":7393,"completedRideValue":118180900.0,"advertising":4300000.0},{"n":4,"year":2024,"calendarMonth":8,"completedOrders":10349,"completedRideValue":165171900.0,"advertising":3700000.0},{"n":5,"year":2024,"calendarMonth":9,"completedOrders":12539,"completedRideValue":195750600.0,"advertising":3500000.0},{"n":6,"year":2024,"calendarMonth":10,"completedOrders":15323,"completedRideValue":238930200.0,"advertising":3300000.0},{"n":7,"year":2024,"calendarMonth":11,"completedOrders":16733,"completedRideValue":260987600.0,"advertising":6300000.0},{"n":8,"year":2024,"calendarMonth":12,"completedOrders":20671,"completedRideValue":334202200.0,"advertising":7000000.0},{"n":9,"year":2025,"calendarMonth":1,"completedOrders":23377,"completedRideValue":390874500.0,"advertising":6500000.0},{"n":10,"year":2025,"calendarMonth":2,"completedOrders":23677,"completedRideValue":366761300.0,"advertising":8000000.0},{"n":11,"year":2025,"calendarMonth":3,"completedOrders":28628,"completedRideValue":484405300.0,"advertising":10750000.0},{"n":12,"year":2025,"calendarMonth":4,"completedOrders":32518,"completedRideValue":593922100.0,"advertising":10500000.0}]},{"key":"pati","name":"Pati","status":"problem","province":"Central Java","population":109831,"officeMonthly":1000000,"managerMonthly":0,"title":{"en":"Insufficient investment in user acquisition","id":"Investasi untuk akuisisi pengguna tidak mencukupi"},"summary":{"en":"The service generated orders, but promotion was almost absent. Without systematic advertising, the user base did not grow enough, so order volume stayed broadly flat and could not cover fixed costs.","id":"Pesanan mulai muncul, tetapi promosi hampir tidak dilakukan. Tanpa iklan yang sistematis, basis pengguna tidak tumbuh cukup besar sehingga volume pesanan relatif datar dan tidak mampu menutup biaya tetap."},"bullets":{"en":["Only about 2 million IDR was invested in advertising over 12 months.","Order volume fluctuated around the same level without sustainable growth.","The project does not pay back within the first year."],"id":["Hanya sekitar 2 juta IDR yang diinvestasikan untuk iklan selama 12 bulan.","Volume pesanan berfluktuasi di tingkat yang hampir sama tanpa pertumbuhan berkelanjutan.","Proyek belum kembali modal dalam tahun pertama."]},"rows":[{"n":1,"year":2024,"calendarMonth":6,"completedOrders":443,"completedRideValue":8753100.0,"advertising":0.0},{"n":2,"year":2024,"calendarMonth":7,"completedOrders":1103,"completedRideValue":22493000.0,"advertising":0.0},{"n":3,"year":2024,"calendarMonth":8,"completedOrders":1281,"completedRideValue":21963900.0,"advertising":0.0},{"n":4,"year":2024,"calendarMonth":9,"completedOrders":1069,"completedRideValue":21390900.0,"advertising":300000.0},{"n":5,"year":2024,"calendarMonth":10,"completedOrders":1255,"completedRideValue":23456100.0,"advertising":0.0},{"n":6,"year":2024,"calendarMonth":11,"completedOrders":1267,"completedRideValue":22153000.0,"advertising":0.0},{"n":7,"year":2024,"calendarMonth":12,"completedOrders":1438,"completedRideValue":30184900.0,"advertising":1700000.0},{"n":8,"year":2025,"calendarMonth":1,"completedOrders":1338,"completedRideValue":24964100.0,"advertising":0.0},{"n":9,"year":2025,"calendarMonth":2,"completedOrders":1282,"completedRideValue":23513000.0,"advertising":0.0},{"n":10,"year":2025,"calendarMonth":3,"completedOrders":1578,"completedRideValue":28845900.0,"advertising":0.0},{"n":11,"year":2025,"calendarMonth":4,"completedOrders":1761,"completedRideValue":37758000.0,"advertising":0.0},{"n":12,"year":2025,"calendarMonth":5,"completedOrders":1547,"completedRideValue":27617400.0,"advertising":0.0}]},{"key":"tuban","name":"Tuban","status":"problem","province":"East Java","population":91980,"officeMonthly":2150000,"managerMonthly":1500000,"title":{"en":"Investment was stopped before demand could form","id":"Investasi dihentikan sebelum permintaan terbentuk"},"summary":{"en":"Advertising investment was substantial at launch, but the first results were weaker than expected. Promotion was almost stopped after four months, before the service had time to build stable demand.","id":"Investasi iklan cukup besar pada awal peluncuran, tetapi hasil awal lebih lemah dari harapan. Setelah empat bulan promosi hampir dihentikan, sebelum layanan sempat membentuk permintaan yang stabil."},"bullets":{"en":["Almost the entire advertising budget was spent in the first four months.","After a weak start, promotion was almost completely stopped.","Order volume remained extremely low, and the project does not pay back in the first year."],"id":["Hampir seluruh anggaran iklan digunakan dalam empat bulan pertama.","Setelah awal yang lemah, promosi hampir sepenuhnya dihentikan.","Volume pesanan tetap sangat rendah dan proyek belum kembali modal dalam tahun pertama."]},"rows":[{"n":1,"year":2023,"calendarMonth":3,"completedOrders":1,"completedRideValue":10200.0,"advertising":8500000.0},{"n":2,"year":2023,"calendarMonth":4,"completedOrders":23,"completedRideValue":497400.0,"advertising":4400000.0},{"n":3,"year":2023,"calendarMonth":5,"completedOrders":26,"completedRideValue":289400.0,"advertising":3900000.0},{"n":4,"year":2023,"calendarMonth":6,"completedOrders":20,"completedRideValue":352200.0,"advertising":2800000.0},{"n":5,"year":2023,"calendarMonth":7,"completedOrders":31,"completedRideValue":525700.0,"advertising":0.0},{"n":6,"year":2023,"calendarMonth":8,"completedOrders":18,"completedRideValue":414200.0,"advertising":0.0},{"n":7,"year":2023,"calendarMonth":9,"completedOrders":51,"completedRideValue":619300.0,"advertising":90000.0},{"n":8,"year":2023,"calendarMonth":10,"completedOrders":41,"completedRideValue":747500.0,"advertising":0.0},{"n":9,"year":2023,"calendarMonth":11,"completedOrders":68,"completedRideValue":1000700.0,"advertising":100000.0},{"n":10,"year":2023,"calendarMonth":12,"completedOrders":78,"completedRideValue":1493900.0,"advertising":0.0},{"n":11,"year":2024,"calendarMonth":1,"completedOrders":50,"completedRideValue":1324400.0,"advertising":0.0},{"n":12,"year":2024,"calendarMonth":2,"completedOrders":33,"completedRideValue":611700.0,"advertising":0.0}]}];
  let detailChart=null;
  let currentCaseKey=null;

  const $=(selector,root=document)=>root.querySelector(selector);
  const esc=value=>String(value??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
  const t=(key,vars={})=>Localization.t(key,vars);
  const locale=()=>Localization.numberLocale();
  const fmt=value=>Math.round(Number(value)||0).toLocaleString(locale());
  const money=value=>`${Math.round(Number(value)||0).toLocaleString(locale())} IDR`;
  const compact=value=>FinancialEngine.formatCurrencyCompact(value);
  const langKey=()=>({'id-ID':'id','en-US':'en'}[Localization.getLanguage()]||'id');

  const provinceTranslations={
    'Central Sulawesi':{id:'Sulawesi Tengah',en:'Central Sulawesi'},
    'Riau':{id:'Riau',en:'Riau'},
    'Central Java':{id:'Jawa Tengah',en:'Central Java'},
    'East Java':{id:'Jawa Timur',en:'East Java'}
  };
  function provinceName(name){
    const item=provinceTranslations[name];
    return item?.[langKey()]||name;
  }
  function normalizeCase(raw){
    const commissionRate=FinancialEngine.recommendedCommissionForPopulation(raw.population,raw.province);
    const fixed=FinancialEngine.operatingExpenseRatesForPopulation(raw.population);
    const initialFee=FinancialEngine.initialPaymentForPopulation(raw.population);
    let accumulated=0;
    const rows=raw.rows.map((source,index)=>{
      const monthNo=index+1;
      const completed=Number(source.completedOrders)||0;
      const gross=Number(source.completedRideValue)||0;
      const avgFare=completed?gross/completed:0;
      const commissionRevenue=gross*commissionRate/100;
      const uniformInvestment=[1,4,7,10].includes(monthNo)?6400000:0;
      const uniformSales=[1,4,7,10].includes(monthNo)?7000000:0;
      const advertising=Number(source.advertising)||0;
      const royaltyRate=FinancialEngine.royaltyRateForGrossRevenue(commissionRevenue);
      const royalty=commissionRevenue*royaltyRate/100;
      const assistant=FinancialEngine.assistantFeeForGrossRevenue(commissionRevenue);
      const smsRate=FinancialEngine.smsRateForGrossRevenue(commissionRevenue);
      const sms=completed*0.20*smsRate;
      const office=Number.isFinite(Number(raw.officeMonthly))?Number(raw.officeMonthly):fixed.officeRent;
      const manager=Number.isFinite(Number(raw.managerMonthly))?Number(raw.managerMonthly):fixed.managerSalary;
      const operatingExpenses=office+manager+assistant+sms+royalty;
      const fee=monthNo===1?initialFee:0;
      const revenue=commissionRevenue+uniformSales;
      const net=revenue-advertising-uniformInvestment-operatingExpenses-fee;
      accumulated+=net;
      return {
        ...source,monthNo,completed,ridesPerDay:Math.round(completed/30),avgFare,
        commissionRate,commissionRevenue,uniformInvestment,uniformSales,advertising,
        royaltyRate,royalty,assistant,sms,office,manager,operatingExpenses,
        initialFee:fee,revenue,net,accumulated
      };
    });
    const total=key=>rows.reduce((sum,row)=>sum+(Number(row[key])||0),0);
    const completedTotal=total('completed');
    const grossTotal=rows.reduce((sum,row)=>sum+(Number(row.completedRideValue)||0),0);
    const paybackRow=rows.find(row=>row.accumulated>=0);
    return {
      ...raw,commissionRate,rows,
      initialFee,totalInvestment:initialFee+total('advertising')+total('uniformInvestment'),
      totalRevenue:total('revenue'),
      totalOperatingExpenses:total('operatingExpenses'),
      yearResult:total('net'),
      completedTotal,
      avgFare:completedTotal?grossTotal/completedTotal:0,
      advertisingTotal:total('advertising'),
      payback:paybackRow?paybackRow.monthNo:null
    };
  }
  const CASES=()=>RAW_CASES.map(normalizeCase);

  function showModal(id){
    const modal=document.getElementById(id);
    if(!modal)return;
    modal.hidden=false;
    modal.setAttribute('aria-hidden','false');
    document.body.classList.add('real-examples-modal-open');
    requestAnimationFrame(()=>modal.querySelector('[data-real-close]')?.focus());
  }
  function hideModal(id){
    const modal=document.getElementById(id);
    if(!modal)return;
    modal.hidden=true;
    modal.setAttribute('aria-hidden','true');
    if(!document.querySelector('.real-examples-modal:not([hidden])'))document.body.classList.remove('real-examples-modal-open');
    if(id==='realCaseModal'&&detailChart){detailChart.destroy();detailChart=null;}
  }
  function statusLabel(status){return t(status==='success'?'realExamplesSuccess':'realExamplesProblem');}
  function paybackLabel(value){return value?t('realExamplesMonthPayback',{n:value}):t('realExamplesNoPayback');}
  function caseCopy(c,key){
    const lk=langKey();
    return c[key]?.[lk]||c[key]?.id||'';
  }
  function cardHtml(c){
    const bullets=c.bullets[langKey()]||c.bullets.id;
    return `<article class="real-case-card real-case-card-button ${c.status}" data-real-case="${esc(c.key)}" role="button" tabindex="0" aria-label="${esc(t('realExamplesOpenCase'))}: ${esc(c.name)}">
      <div class="real-case-card-head">
        <div>
          <span class="real-case-tag ${c.status}">${esc(statusLabel(c.status))}</span>
          <h4>${esc(c.name)}</h4>
          <div class="real-case-meta">${esc(provinceName(c.province))} · ${fmt(c.population)} ${esc(t('realExamplesResidents'))}</div>
        </div>
        <span class="real-case-card-arrow" aria-hidden="true">→</span>
      </div>
      <h5>${esc(caseCopy(c,'title'))}</h5>
      <ul>${bullets.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>
      <div class="real-case-card-metrics">
        <div><small>${esc(t('realExamplesYearResult'))}</small><strong class="${c.yearResult>=0?'positive':'negative'}">${compact(c.yearResult)}</strong></div>
        <div><small>${esc(t('realExamplesPayback'))}</small><strong>${esc(paybackLabel(c.payback))}</strong></div>
      </div>
    </article>`;
  }
  function renderOverview(){
    const body=document.getElementById('realExamplesBody');
    if(!body)return;
    const cases=CASES();
    const good=cases.filter(c=>c.status==='success');
    const bad=cases.filter(c=>c.status==='problem');
    body.innerHTML=`<div class="real-case-columns">
        <section class="real-case-column success">
          <div class="real-case-column-title"><span class="real-case-column-icon">✓</span><div><h3>${esc(t('realExamplesSuccessTitle'))}</h3><p>${esc(t('realExamplesSuccessSubtitle'))}</p></div></div>
          ${good.map(cardHtml).join('')}
        </section>
        <section class="real-case-column problem">
          <div class="real-case-column-title"><span class="real-case-column-icon">!</span><div><h3>${esc(t('realExamplesProblemTitle'))}</h3><p>${esc(t('realExamplesProblemSubtitle'))}</p></div></div>
          ${bad.map(cardHtml).join('')}
        </section>
      </div>`;
  }
  function openOverview(){renderOverview();showModal('realExamplesModal');}
  function tableSection(labelKey,rows,sectionClass){
    return `<tr class="real-case-section ${sectionClass}"><th colspan="13">${esc(t(labelKey))}</th></tr>${rows.join('')}`;
  }
  function cell(value,type='money',signed=false){
    const n=Number(value)||0;
    const cls=signed?(n>=0?'positive':'negative'):'';
    if(type==='number')return `<td class="${cls}">${fmt(n)}</td>`;
    if(type==='fare')return `<td class="${cls}">${money(n)}</td>`;
    return `<td class="${cls}">${n?fmt(n):'—'}</td>`;
  }
  function dataRow(labelKey,c,key,type='money',signed=false,rowClass=''){
    return `<tr${rowClass?` class="${rowClass}"`:''}><th>${esc(t(labelKey))}</th>${c.rows.map(r=>cell(r[key],type,signed)).join('')}</tr>`;
  }
  function caseTable(c){
    const investment=[
      dataRow('initialPurchase',c,'initialFee'),
      dataRow('marketingInvestment',c,'advertising'),
      dataRow('attributesInvestment',c,'uniformInvestment')
    ];
    const income=[
      dataRow('uniformSales',c,'uniformSales'),
      dataRow('ridesPerDay',c,'ridesPerDay','number'),
      dataRow('ridesPerMonth',c,'completed','number'),
      dataRow('averageRidePrice',c,'avgFare','fare'),
      dataRow('commissionFromCompletedRidesValue',c,'commissionRevenue'),
      dataRow('realExamplesTotalRevenue',c,'revenue','money',false,'real-case-total-row')
    ];
    const expenses=[
      dataRow('officeRent',c,'office'),
      dataRow('managerSalary',c,'manager'),
      dataRow('assistente',c,'assistant'),
      dataRow('smsExpense',c,'sms'),
      dataRow('royaltyCombined',c,'royalty'),
      dataRow('totalOperatingExpenses',c,'operatingExpenses','money',false,'real-case-total-row')
    ];
    const profit=[
      dataRow('netProfit',c,'net','money',true),
      dataRow('accumulatedCashFlow',c,'accumulated','money',true)
    ];
    const heads=c.rows.map(r=>`<th><span>${r.monthNo}</span><small>${String(r.calendarMonth).padStart(2,'0')}/${r.year}</small></th>`).join('');
    return `<div class="real-case-table-scroll"><table class="real-case-table">
      <thead><tr><th>${esc(t('realExamplesIndicator'))}</th>${heads}</tr></thead>
      <tbody>
        ${tableSection('investment',investment,'investment')}
        ${tableSection('orderIndicators',income,'income')}
        ${tableSection('operatingExpenses',expenses,'expenses')}
        ${tableSection('profitCash',profit,'profit')}
      </tbody>
    </table></div>`;
  }
  function renderDetail(c){
    const body=document.getElementById('realCaseBody');
    if(!body)return;
    document.getElementById('realCaseTitle').textContent=c.name;
    document.getElementById('realCaseSubtitle').textContent=`${provinceName(c.province)} · ${fmt(c.population)} ${t('realExamplesResidents')}`;
    body.innerHTML=`<div class="real-case-hero ${c.status}">
      <div class="real-case-tag ${c.status}">${esc(statusLabel(c.status))}</div>
      <div><h3>${esc(caseCopy(c,'title'))}</h3><p>${esc(caseCopy(c,'summary'))}</p></div>
    </div>
    <div class="real-case-kpis">
      <div><small>${esc(t('realExamplesInvestment12'))}</small><strong>${compact(c.totalInvestment)}</strong></div>
      <div><small>${esc(t('realExamplesTotalRevenue'))}</small><strong>${compact(c.totalRevenue)}</strong></div>
      <div><small>${esc(t('realExamplesFinancialResult'))}</small><strong class="${c.yearResult>=0?'positive':'negative'}">${compact(c.yearResult)}</strong></div>
      <div><small>${esc(t('realExamplesPayback'))}</small><strong>${esc(paybackLabel(c.payback))}</strong></div>
      <div><small>${esc(t('realExamplesAverageFare'))}</small><strong>${money(c.avgFare)}</strong></div>
      <div><small>${esc(t('realExamplesCommissionRate'))}</small><strong>${c.commissionRate}%</strong></div>
      <div><small>${esc(t('realExamplesCompletedOrders'))}</small><strong>${fmt(c.completedTotal)}</strong></div>
      <div><small>${esc(t('realExamplesActualAdvertising'))}</small><strong>${compact(c.advertisingTotal)}</strong></div>
    </div>
    ${caseTable(c)}
    <div class="real-case-chart-wrap"><h3>${esc(t('realExamplesChartTitle'))}</h3><canvas id="realCaseChart"></canvas></div>`;
    requestAnimationFrame(()=>renderChart(c));
  }
  function renderChart(c){
    const canvas=document.getElementById('realCaseChart');
    if(!canvas||typeof Chart==='undefined')return;
    if(detailChart)detailChart.destroy();
    detailChart=new Chart(canvas,{
      type:'bar',
      data:{
        labels:c.rows.map(r=>String(r.monthNo)),
        datasets:[
          {type:'bar',label:t('monthlyNetProfit'),data:c.rows.map(r=>r.net),backgroundColor:'rgba(91,146,76,.68)',borderColor:'rgba(74,123,62,1)',borderWidth:1,borderRadius:5},
          {type:'line',label:t('accumulatedNetProfit'),data:c.rows.map(r=>r.accumulated),borderColor:'#294f72',backgroundColor:'#294f72',borderWidth:2.2,pointRadius:2.5,tension:.22}
        ]
      },
      options:{
        responsive:true,maintainAspectRatio:false,
        plugins:{legend:{position:'bottom',labels:{boxWidth:11,usePointStyle:true}}},
        scales:{
          x:{grid:{display:false},title:{display:true,text:t('realExamplesMonth')}},
          y:{grid:{color:'rgba(107,128,151,.15)'},ticks:{callback:v=>FinancialEngine.formatMoney(v,true)}}
        }
      }
    });
  }
  function openCase(key){
    const c=CASES().find(item=>item.key===key);
    if(!c)return;
    currentCaseKey=key;
    hideModal('realExamplesModal');
    renderDetail(c);
    showModal('realCaseModal');
  }
  function rerenderOpenModal(){
    if(!document.getElementById('realExamplesModal')?.hidden)renderOverview();
    if(!document.getElementById('realCaseModal')?.hidden&&currentCaseKey){
      const c=CASES().find(item=>item.key===currentCaseKey);
      if(c)renderDetail(c);
    }
  }
  function init(){
    document.getElementById('realExamplesBtn')?.addEventListener('click',openOverview);
    document.body.addEventListener('click',event=>{
      const opener=event.target.closest('[data-real-case]');
      if(opener){openCase(opener.dataset.realCase);return;}
      const closer=event.target.closest('[data-real-close]');
      if(closer){hideModal(closer.dataset.realClose);return;}
      if(event.target.closest('[data-real-back]')){hideModal('realCaseModal');openOverview();return;}
    });
    document.addEventListener('keydown',event=>{
      const card=event.target.closest?.('[data-real-case][role="button"]');
      if(card&&(event.key==='Enter'||event.key===' ')){
        event.preventDefault();
        openCase(card.dataset.realCase);
        return;
      }
      if(event.key!=='Escape')return;
      if(!document.getElementById('realCaseModal')?.hidden)hideModal('realCaseModal');
      else if(!document.getElementById('realExamplesModal')?.hidden)hideModal('realExamplesModal');
    });
    ['languageSelect','startLanguageSelect','mobileLanguageSelect','mobileDashboardLanguageSelect'].forEach(id=>{
      document.getElementById(id)?.addEventListener('change',()=>requestAnimationFrame(rerenderOpenModal));
    });
  }
  return{init,openOverview};
})();
document.addEventListener('DOMContentLoaded',RealExamples.init);
